class C{String s(boolean p,String[]g){int R=g.length,C=g[0].length(),q[]=new int[R*C],v[]=new int[R*C];long A=0;for(int r=0;r<R;r++){var s=g[r];for(int c=0;c<C;c++){char h=s.charAt(c);if(h<48|h>57)continue;int b=c,n=0;for(;c<C&&(h=s.charAt(c))>47&h<58;c++)n=n*10+h-48;int o=0;for(int y=Math.max(0,r-1);y<=Math.min(R-1,r+1);y++)for(int x=Math.max(0,b-1);x<=Math.min(C-1,c);x++){h=g[y].charAt(x);if((h<48|h>57)&h!=46)o=1;if(h==42){int i=y*C+x;v[i]=q[i]++<1?n:v[i]*n;}}if(p&o>0)A+=n;c--;}}if(!p)for(int i=0;i<q.length;i++)if(q[i]==2)A+=v[i];return A+"";}}
